// McpPromptPlaybooks.cpp
// Per-domain playbooks served as MCP prompts: the capabilities to reach for in order, and the traps of the domain (what
// goes wrong without a word, and how to see it). Data only; general Unreal practice, nothing project-specific.
#include "MCP/Primitives/McpPromptCatalog.h"

namespace
{
const FMcpPromptArgumentSpec PlaybookGoal{TEXT("goal"), false, TEXT("What you want to build, in your own words")};
}

TArray<FMcpWorkflowPrompt> McpPlaybookPrompts()
{
	return {
		FMcpWorkflowPrompt{ TEXT("blueprint-logic"), TEXT("Write gameplay logic in a Blueprint"),
			TEXT("Read and write a Blueprint's graphs as code or in one batch, check them before Play, and watch values while it runs."),
			{ PlaybookGoal },
			{ {TEXT("Read the graph you will change as code, each statement tagged with its node."), TEXT("blueprint.read_graph_as_code"), TEXT("manage_blueprint"), TEXT("read_graph_as_code"), TEXT("ue://asset/{assetPath}"), TEXT("Read-only.")},
			  {TEXT("Write an event's or a function's body from code (Epic's S-expression grammar); a statement left unchanged keeps its node."), TEXT("blueprint.write_graph_from_code"), TEXT("manage_blueprint"), TEXT("write_graph_from_code"), TEXT(""), TEXT("A refusal changes nothing, and a body that would break the compile is rolled back.")},
			  {TEXT("Or make many nodes and wires in one batch: name nodes with an id and wire them as $id.Pin."), TEXT("blueprint.build_graph"), TEXT("manage_blueprint"), TEXT("build_graph"), TEXT(""), TEXT("It stops at the first failing step; dryRun checks every step first.")},
			  {TEXT("Lint before Play: unreachable nodes, heavy work on Tick, reads that can be None, loops that cannot end."), TEXT("blueprint.lint_blueprint"), TEXT("manage_blueprint"), TEXT("lint_blueprint"), TEXT(""), TEXT("Read-only.")},
			  {TEXT("Compile and read the diagnostics."), TEXT("blueprint.compile"), TEXT("manage_blueprint"), TEXT("compile"), TEXT(""), TEXT("Errors come back with the node that has them.")},
			  {TEXT("In Play, record the pin values of chosen nodes each time they run, without pausing."), TEXT("inspect.set_logpoints"), TEXT("inspect"), TEXT("set_logpoints"), TEXT(""), TEXT("Play only; the game keeps running.")} },
			{ TEXT("CreateWidget and SpawnActorFromClass take their class from the Class input pin (set_pin_default_value with the class path), not from a node property; a cast node takes targetClass."),
			  TEXT("An exec output holds one wire: fan out through a Sequence node. An exec input accepts many."),
			  TEXT("A function of another class needs memberName plus memberClass (SetText on /Script/UMG.TextBlock, for example); functionName alone finds only what the Blueprint's own class can call."),
			  TEXT("A container variable gets its default after it exists: add the variable, then edit_variable set_default with the JSON array."),
			  TEXT("Every graph edit compiles: a missing Target or Object wire shows in the diagnostics of the call that caused it, so read them before the next edit."),
			  TEXT("To cut wires, use delete_node with deleteScope pin_links; deleting a node takes its wires with it.") } },
		FMcpWorkflowPrompt{ TEXT("input-setup"), TEXT("Make keys and buttons drive a pawn (Enhanced Input)"),
			TEXT("Create input actions and a mapping context, handle the actions in the graph, register the context, and prove a key moves the pawn."),
			{ PlaybookGoal },
			{ {TEXT("Create an input action per verb (Move, Jump, Fire)."), TEXT("manage_networking.create_input_action"), TEXT("manage_networking"), TEXT("create_input_action"), TEXT(""), TEXT("Creates assets.")},
			  {TEXT("Create a mapping context and map keys to the actions."), TEXT("manage_networking.create_input_mapping_context"), TEXT("manage_networking"), TEXT("create_input_mapping_context"), TEXT(""), TEXT("Creates an asset.")},
			  {TEXT("Handle each action in the pawn or controller with an EnhancedInputAction event node made with inputActionPath, and call AddMappingContext in BeginPlay."), TEXT("blueprint.build_graph"), TEXT("manage_blueprint"), TEXT("build_graph"), TEXT(""), TEXT("The action is bound when the node is made; a node made without it never fires.")},
			  {TEXT("Start Play."), TEXT("control_editor.play"), TEXT("control_editor"), TEXT("play"), TEXT(""), TEXT("Play changes nothing in the level.")},
			  {TEXT("Press a key through the pawn, then release it."), TEXT("control_editor.simulate_input"), TEXT("control_editor"), TEXT("simulate_input"), TEXT(""), TEXT("Always send key_up after key_down, or the pawn keeps moving.")} },
			{ TEXT("Nothing reacts until AddMappingContext registers the mapping context on the local player's Enhanced Input subsystem, usually in the player controller's or pawn's BeginPlay. No compile error or warning says it is missing: when input does nothing, look for Add Mapping Context first."),
			  TEXT("For a quick test, configure_input enable_mapping turns a context on in the running Play; the game itself still needs Add Mapping Context in BeginPlay."),
			  TEXT("Prove input by state, not by the reply: read the pawn's transform, send key_down, read it again, then key_up. A key that reached Play can still bind to nothing."),
			  TEXT("Something that lives a moment (a projectile, a flash) can be gone before the next call: check a value the action sets instead.") } },
		FMcpWorkflowPrompt{ TEXT("widget-ui"), TEXT("Build a HUD or menu (UMG)"),
			TEXT("Make a Widget Blueprint, build its tree in one call, lay it out by relations, audit it at several screen sizes, and press it in Play."),
			{ PlaybookGoal },
			{ {TEXT("Create the Widget Blueprint."), TEXT("blueprint.create_widget_blueprint"), TEXT("manage_blueprint"), TEXT("create_widget_blueprint"), TEXT(""), TEXT("Creates an asset.")},
			  {TEXT("Build the widget tree in one call."), TEXT("blueprint.add_widget_tree"), TEXT("manage_blueprint"), TEXT("add_widget_tree"), TEXT(""), TEXT("dryRun checks every step first.")},
			  {TEXT("Place a Canvas Panel's children by relations (left of, below, centred, inset from an edge); anchors follow what holds each one."), TEXT("blueprint.arrange_widgets"), TEXT("manage_blueprint"), TEXT("arrange_widgets"), TEXT(""), TEXT("One undo step; dryRun reports the boxes and changes nothing.")},
			  {TEXT("Audit the layout at several resolutions: overlaps, clipped text, safe zone, touch size, contrast."), TEXT("blueprint.audit_widget"), TEXT("manage_blueprint"), TEXT("audit_widget"), TEXT(""), TEXT("Read-only.")},
			  {TEXT("See it drawn without Play."), TEXT("blueprint.preview_widget"), TEXT("manage_blueprint"), TEXT("preview_widget"), TEXT(""), TEXT("Read-only.")},
			  {TEXT("In Play, list the live widgets (widget_list) and press one by name (widget_click)."), TEXT("control_editor.simulate_input"), TEXT("control_editor"), TEXT("simulate_input"), TEXT(""), TEXT("Play only.")} },
			{ TEXT("After any widget edit, read the tree back (get_widget_info) and compare the slot count with what you expect: a duplicate is invisible in a screenshot and in a success reply."),
			  TEXT("A capture of the game view holds no UMG, which is drawn over the scene: use preview_widget, or capture the editor window, to see the UI."),
			  TEXT("Once a click lands in the Play viewport it takes the mouse, and later clicks go to the viewport: press widgets with widget_click by name rather than by coordinates."),
			  TEXT("A widget in the viewport can still show nothing (hidden, transparent, zero-sized, covered): inspect explain names which.") } },
		FMcpWorkflowPrompt{ TEXT("niagara-vfx"), TEXT("Author a Niagara effect"),
			TEXT("Make a system and an emitter, add modules and a renderer with a material, and check that it really draws."),
			{ PlaybookGoal },
			{ {TEXT("Create the system (kind niagara_system) and the emitter (kind niagara_emitter): two assets."), TEXT("manage_effect.create_effect"), TEXT("manage_effect"), TEXT("create_effect"), TEXT(""), TEXT("Creates assets.")},
			  {TEXT("Add the emitter to the system, naming both systemPath and emitterPath."), TEXT("manage_effect.edit_niagara_system"), TEXT("manage_effect"), TEXT("edit_niagara_system"), TEXT(""), TEXT("It instances an existing emitter asset.")},
			  {TEXT("Add spawn rate, initialize particle, velocity and a sprite renderer given materialPath."), TEXT("manage_effect.add_niagara_module"), TEXT("manage_effect"), TEXT("add_niagara_module"), TEXT(""), TEXT("Follow any dependencyHint the reply gives.")},
			  {TEXT("Read it back: modules, static switches, validation."), TEXT("manage_effect.get_niagara_info"), TEXT("manage_effect"), TEXT("get_niagara_info"), TEXT(""), TEXT("Read-only.")},
			  {TEXT("Turn viewport realtime on to see it run in the editor."), TEXT("control_editor.configure_viewport"), TEXT("control_editor"), TEXT("configure_viewport"), TEXT(""), TEXT("Changes only the viewport.")} },
			{ TEXT("Three separate reasons a valid-looking system draws nothing: the viewport is not realtime (Niagara does not tick), the renderer has no material (validation does not catch it), or the material lacks its Niagara usage flag (a renderer given materialPath sets it)."),
			  TEXT("Static switches gate inputs: a size or a width does nothing while its Mode switch is Unset; get_niagara_info lists staticSwitches and set_parameter_value sets one (Direct Set)."),
			  TEXT("A force module needs its solver after it: add what the reply's dependencyHint names (SolveForcesAndVelocity).") } },
		FMcpWorkflowPrompt{ TEXT("material-authoring"), TEXT("Build a material"),
			TEXT("Create a material, build its graph in one batch, compile it, make instances, and put them on actors."),
			{ PlaybookGoal },
			{ {TEXT("Create the material."), TEXT("material.create_material"), TEXT("manage_asset"), TEXT("create_material"), TEXT(""), TEXT("Creates an asset.")},
			  {TEXT("Build the graph in one batch: nodes, wires and material properties."), TEXT("material.add_material_node"), TEXT("manage_asset"), TEXT("add_material_node"), TEXT(""), TEXT("dryRun checks every step first.")},
			  {TEXT("Recompile and read compiled and compileErrors."), TEXT("material.compile_material"), TEXT("manage_asset"), TEXT("compile_material"), TEXT(""), TEXT("Saved unless save is false.")},
			  {TEXT("Make instances for variants instead of copying the material."), TEXT("material.create_material_instance"), TEXT("manage_asset"), TEXT("create_material_instance"), TEXT(""), TEXT("Creates an asset.")},
			  {TEXT("Put it on actors: a slot, a component, or many actors at once."), TEXT("control_actor.set_material"), TEXT("control_actor"), TEXT("set_material"), TEXT(""), TEXT("One undo step.")} },
			{ TEXT("A material that does not compile renders as the default material: compile_material answers compiled false with compileErrors; fix those before judging the look."),
			  TEXT("Auto-exposure re-normalises every frame, so a change of albedo or light can look like no change: first prove the material reaches the surface with an extreme value (pure red), or measure with analyze_view."),
			  TEXT("A material on particles, ribbons or other special geometry needs the matching usage flag; one the engine sets by itself during Play is not saved.") } },
		FMcpWorkflowPrompt{ TEXT("world-building"), TEXT("Shape terrain and lay out a level"),
			TEXT("Make and shape a landscape, route roads over it, add buildings and modular layouts, and keep every placement sound."),
			{ PlaybookGoal },
			{ {TEXT("Create the landscape."), TEXT("build_environment.create_landscape"), TEXT("build_environment"), TEXT("create_landscape"), TEXT(""), TEXT("One undo step.")},
			  {TEXT("Raise, lower, smooth or flatten areas."), TEXT("build_environment.sculpt"), TEXT("build_environment"), TEXT("sculpt"), TEXT(""), TEXT("One undo step.")},
			  {TEXT("Wear the terrain down as water does; the reply lists its rivers."), TEXT("build_environment.erode_landscape"), TEXT("build_environment"), TEXT("erode_landscape"), TEXT(""), TEXT("dryRun computes without writing.")},
			  {TEXT("Route a drivable road under a grade limit, then send its nextCall (a road slab) or landscapeSplineCall (a spline that shapes the terrain)."), TEXT("build_environment.plan_road"), TEXT("build_environment"), TEXT("plan_road"), TEXT(""), TEXT("Read-only; the calls it hands back make the road.")},
			  {TEXT("Add roofs over any footprint, boxes, stairs and arches."), TEXT("manage_geometry.create_primitive"), TEXT("manage_geometry"), TEXT("create_primitive"), TEXT(""), TEXT("One undo step each.")},
			  {TEXT("Lay a modular kit out over a grid with every joint matching."), TEXT("build_environment.assemble_modules"), TEXT("build_environment"), TEXT("assemble_modules"), TEXT(""), TEXT("One undo step; dryRun lays it out without spawning.")},
			  {TEXT("Settle sunk, floating or overlapping actors."), TEXT("control_actor.fix_placement"), TEXT("control_actor"), TEXT("fix_placement"), TEXT(""), TEXT("One undo step; dryRun reports the moves.")},
			  {TEXT("Save the level."), TEXT("manage_level.save"), TEXT("manage_level"), TEXT("save"), TEXT(""), TEXT("Writes the level to disk.")} },
			{ TEXT("create_primitive meshes have no collision: traces and players pass through them, and what stands on them reads nothing below it, until configure_mesh_collision gives them some."),
			  TEXT("Read each reply's warnings: sunk, floating, intersecting and z-fighting actors are named on the call that caused them; tag a deliberate placement mcp.placement.ok."),
			  TEXT("A level slab laid across a side slope cuts into the uphill side: shape the terrain to the road (landscapeSplineCall) rather than lifting the slab."),
			  TEXT("Opening another level over unsaved changes is refused (DIRTY_PACKAGES) until you choose saveDirtyPackages or discardUnsaved."),
			  TEXT("Auto-exposure hides lighting changes: judge them with analyze_view or a fixed exposure, not by eye.") } },
		FMcpWorkflowPrompt{ TEXT("animation-setup"), TEXT("Make a character animate"),
			TEXT("Lay out a locomotion blend space, build the Anim Blueprint's state machine, wire it to the output pose, and check the pose."),
			{ PlaybookGoal },
			{ {TEXT("Lay out a locomotion blend space from the clips' own motion."), TEXT("animation_physics.auto_blend_space"), TEXT("animation_physics"), TEXT("auto_blend_space"), TEXT(""), TEXT("One undo step; dryRun measures without writing.")},
			  {TEXT("Add the state machine, its states with their animations, and the transitions."), TEXT("animation_physics.edit_anim_graph"), TEXT("animation_physics"), TEXT("edit_anim_graph"), TEXT(""), TEXT("Read the reply: it says which state is the entry.")},
			  {TEXT("Give each transition its rule: a variable, a comparison and a value."), TEXT("animation_physics.set_transition_rules"), TEXT("animation_physics"), TEXT("set_transition_rules"), TEXT(""), TEXT("A rule without a variable stays false.")},
			  {TEXT("Wire the state machine's Pose to the Output Pose's Result."), TEXT("blueprint.connect_pins"), TEXT("manage_blueprint"), TEXT("connect_pins"), TEXT(""), TEXT("Nothing plays without this wire.")},
			  {TEXT("Author a missing clip (kind procedural) or a montage."), TEXT("animation_physics.create_animation_asset"), TEXT("animation_physics"), TEXT("create_animation_asset"), TEXT(""), TEXT("Creates an asset.")} },
			{ TEXT("A state machine not wired to Output Pose leaves the character in its reference pose with no warning: check the Output Pose node's Result pin first."),
			  TEXT("A transition with no rule variable reads false forever: give every transition its condition."),
			  TEXT("A montage plays only through a Slot node in the Anim Blueprint's graph."),
			  TEXT("Judge the pose itself, from a capture of the character in Play: a reference pose is stiff and symmetric, arms straight down.") } },
		FMcpWorkflowPrompt{ TEXT("cinematics"), TEXT("Shoot and render a sequence"),
			TEXT("Frame shots, fly a camera through the scene, cut between the cameras, and render the result."),
			{ PlaybookGoal },
			{ {TEXT("Place a camera so one or two actors sit where you want them on screen, in clear view."), TEXT("sequence.planner.frame_shot"), TEXT("manage_sequence"), TEXT("frame_shot"), TEXT(""), TEXT("One undo step; dryRun answers without writing.")},
			  {TEXT("Fly a camera through points, clear of geometry, keyed into the sequence."), TEXT("sequence.planner.fly_through"), TEXT("manage_sequence"), TEXT("fly_through"), TEXT(""), TEXT("One undo step; dryRun answers without writing.")},
			  {TEXT("Cut between the sequence's cameras as an editor would: no crossing the line, no jump cuts."), TEXT("sequence.planner.auto_edit"), TEXT("manage_sequence"), TEXT("auto_edit"), TEXT(""), TEXT("Rewrites the camera cut track; one undo step.")},
			  {TEXT("Make a render job for the sequence and run it."), TEXT("sequence.mrq.create_render_job"), TEXT("manage_sequence"), TEXT("create_render_job"), TEXT(""), TEXT("Rendering writes files and can take long.")} },
			{ TEXT("Try framings before keeping one: every planner call takes dryRun, and a kept one is a single undo step."),
			  TEXT("Read the sequence back (list_tracks, list_track_keys) before rendering: the camera cut track decides which camera each frame shows."),
			  TEXT("Render a short range first and look at one frame before a long render.") } },
		FMcpWorkflowPrompt{ TEXT("play-testing"), TEXT("Test the game in Play"),
			TEXT("Run the game, walk it with a playtest or an explorer, read what runs, and see what went wrong."),
			{ PlaybookGoal },
			{ {TEXT("For anything timed, restore the editor window and stop background throttling."), TEXT("control_editor.configure_editor"), TEXT("control_editor"), TEXT("restore_editor_window"), TEXT(""), TEXT("Minimize it again when done.")},
			  {TEXT("Start Play."), TEXT("control_editor.play"), TEXT("control_editor"), TEXT("play"), TEXT(""), TEXT("Play changes nothing in the level.")},
			  {TEXT("Walk the player's pawn to a goal and get a verdict with its evidence."), TEXT("control_editor.playtest"), TEXT("control_editor"), TEXT("playtest"), TEXT(""), TEXT("Only in a Play this server started.")},
			  {TEXT("Explore the level for escapes, places the player cannot reach, and traps."), TEXT("control_editor.explore_level"), TEXT("control_editor"), TEXT("explore_level"), TEXT(""), TEXT("Only in a Play this server started.")},
			  {TEXT("Read the running game's actors and variable values."), TEXT("inspect.runtime_report"), TEXT("inspect"), TEXT("runtime_report"), TEXT(""), TEXT("Read-only.")},
			  {TEXT("Read script errors and warnings."), TEXT("system_control.read_log"), TEXT("system_control"), TEXT("read_log"), TEXT(""), TEXT("Read-only.")} },
			{ TEXT("A minimized or background editor runs Play at about 3 fps, so anything timed reads wrong: restore the window (restore_editor_window) for a timed check and minimize it after."),
			  TEXT("A reply with gamePaused true means the game is paused (a title screen, a pause menu): nothing moves until it resumes."),
			  TEXT("Things that live a moment (projectiles, flashes) can vanish between two calls: check the state they change instead."),
			  TEXT("To prove a sound plays, run the console command au.DumpActiveSounds and read the log: it names each playing sound and its volume.") } },
	};
}
